@ApiOperation(value = "手动触发指定文件处理任务", notes = "")
    @ResponseBody
    @GetMapping(value = "handleFileTaskByKey")
    public Response handleFileTaskByKey(@RequestParam String fileTaskNo, @RequestParam(required = false) boolean isSync) {
        log.info("手动触发指定对账任[{}]", fileTaskNo);
        CompletableFuture.runAsync(() -> {
            FileHandleTaskDo fileHandleTaskDo = fileHandleTaskDoTunnel.selectByPrimaryKey(fileTaskNo);
            if (fileHandleTaskDo != null && !fileHandleTaskDo.getHandleStatus().equals(FileHandleStatus.SUCCESS.getCode())) {
                if (isSync) {
                    fileTaskHandleComponent.handle(fileHandleTaskDo);
                } else {
                    List<FileHandleTaskDo> fileHandleTaskDoList = new ArrayList<>();
                    fileHandleTaskDoList.add(fileHandleTaskDo);
                    fileTaskHandleComponent.handleWithThreadPool(fileHandleTaskDoList);
                }
            }
        });
        return Response.ofSuccess();
    }

public void handleWithThreadPool(List<FileHandleTaskDo> reconFileHandleTaskDos) {
        if (CollectionUtils.isEmpty(reconFileHandleTaskDos)) {
            return;
        }
        int length = reconFileHandleTaskDos.size();
        for (int i = 0; i < length; i++) {
            FileHandleTaskDo fileHandleTaskDo = reconFileHandleTaskDos.get(i);
            try {
                taskHandleThreadPoolExecutor.execute(() -> {
                    handle(fileHandleTaskDo);
                });
            } catch (RejectedExecutionException e) {
                log.info("文件处理任务被拒绝:{}", i);
                try {
                    Thread.sleep(Constant.THREAD_SLEEP_TIME);
                } catch (InterruptedException ex) {
                }
                i--;
            }
        }
    }

public int  handle(Integer fileHandleType){

        List<FileHandleRuleOldDo> list=fileHandleRuleOldDoTunnel.selectByHandleType(fileHandleType, RuleStatus.VALID.getCode());
        if(CollectionUtils.isEmpty(list)){
            return 0;
        }

        int count=0;
        for(FileHandleRuleOldDo fileHandleRuleOldDo:list){
            FileInfoOldDo fileInfoOldDo=this.fileInfoOldDoTunnel.selectByFileNo(fileHandleRuleOldDo.getFileNo());
            FileHandleRuleDo fileHandleRuleDo=convert(fileHandleRuleOldDo,fileInfoOldDo);
           int num= fileHandleRuleDoTunnel.insert(fileHandleRuleDo);
           count=count+num;
        }
        return count;
    }
